INSERT INTO ai_result (rate_s, rate_a, rate_b, image_url, member_id, subs_id, apple_count, red_ratio, green_ratio, brown_ratio)
SELECT #{rateS}, #{rateA}, #{rateB}, #{imageUrl}, #{memberId}, subs_id, #{appleCount}, #{redRatio}, #{greenRatio}, #{brownRatio}
FROM subscription
WHERE member_id = #{memberId} AND status = 'ACTIVE'
LIMIT 1;
